{
  "policy_type": "rules",
  "name": "policy_ep_1",
  "rules": [
    {
      "if": [
        {"feature": "vy", "op": "<", "value": -0.5},
        {"feature": "y", "op": ">", "value": 0.2}
      ],
      "then": 2
    },
    {
      "if": [
        {"feature": "theta", "op": ">", "value": 0.1}
      ],
      "then": 3
    },
    {
      "if": [
        {"feature": "theta", "op": "<", "value": -0.1}
      ],
      "then": 1
    },
    {
      "if": [
        {"feature": "x", "op": ">", "value": 0.1}
      ],
      "then": 3
    },
    {
      "if": [
        {"feature": "x", "op": "<", "value": -0.1}
      ],
      "then": 1
    }
  ],
  "default_action": 0,
  "notes": "This initial policy is designed based on general principles of safe landing. The main engine is fired if the lander is descending too quickly. Orientation engines are used to correct the angle and horizontal position. As there are no previous policies, this policy is a baseline to observe initial behavior and collect data for future iterations."
}

